// === Выбрать пост: какой пост из outbox публиковать сейчас ===
// Имя файла задаёт время выхода (по Москве):
//   2026-10-19-0900-slug.json  → 19 октября в 09:00
//   2026-10-19-slug.json       → 19 октября, время из Настроек (default_hour)
//   slug.json (без даты)       → сразу
const cfg = $('Настройки').first().json;
const DEFAULT_HOUR = cfg.default_hour;
const MIN_GAP_MINUTES = cfg.min_gap_minutes;
const s = $getWorkflowStaticData('global');
s.lastSentAt = s.lastSentAt || {};
s.chatByFile = s.chatByFile || {};
s.doneFiles = s.doneFiles || {};   // защита от повтора, если файл не удалился из outbox
const now = Date.now();

if (s.pauseUntil && now < s.pauseUntil) return [];   // пауза после ошибки Telegram

function dueAt(name) {
  const m = name.match(/^(\d{4})-(\d{2})-(\d{2})(?:-(\d{2})(\d{2}))?(?=[-_.])/);
  if (!m) return 0;
  let hh = DEFAULT_HOUR, mm = 0;
  if (m[4] !== undefined && +m[4] < 24 && +m[5] < 60) { hh = +m[4]; mm = +m[5]; }
  return Date.UTC(+m[1], +m[2] - 1, +m[3], hh - 3, mm);   // Москва = UTC+3
}

const listed = $input.all().map(i => i.json).filter(f => f.type === 'file' && f.name.endsWith('.json'));
for (const k of Object.keys(s.doneFiles)) if (!listed.some(f => f.name === k)) delete s.doneFiles[k];
const files = listed
  .filter(f => s.doneFiles[f.name] !== f.sha)
  .map(f => ({ ...f, due: dueAt(f.name) }))
  .filter(f => f.due <= now)
  .sort((a, b) => a.due - b.due || a.name.localeCompare(b.name));

for (const f of files) {
  const chat = s.chatByFile[f.name];
  const last = chat ? s.lastSentAt[chat] : undefined;
  if (last && now - last < MIN_GAP_MINUTES * 60000) continue;   // этот канал ещё «отдыхает»
  return [{ json: { name: f.name, sha: f.sha, url: f.url, due: new Date(f.due).toISOString() } }];
}
return [];

// === Подготовить: проверить канал и собрать сообщение ===
// Два формата поста:
//   { chat_id, text_html, image_base64, image_mime }  — картинка внутри файла
//   { chat_id, text | text_html, img }                — картинка по ссылке: одно сообщение с крупным превью
const cfg = $('Настройки').first().json;
const ALLOWED = [...cfg.allowed, String(cfg.admin_chat_id || '')].filter(Boolean);
const MIN_GAP_MINUTES = cfg.min_gap_minutes;
const CAPTION_LIMIT = cfg.caption_limit;
const s = $getWorkflowStaticData('global');
s.lastSentAt = s.lastSentAt || {};
s.chatByFile = s.chatByFile || {};
const file = $('Выбрать пост').first().json;
const p = $input.first().json;
const chat = String(p.chat_id || '');
s.chatByFile[file.name] = chat;

const base = { file: file.name, sha: file.sha, id: p.id || file.name.replace(/\.json$/, ''), channel: p.channel || '', chat_id: chat, text_html: p.text_html || p.text || '', due: file.due, preview: false };

if (!ALLOWED.includes(chat)) {
  return [{ json: { ...base, action: 'reject', reason: 'Канал ' + chat + ' не в белом списке' } }];
}
const last = s.lastSentAt[chat];
if (last && Date.now() - last < MIN_GAP_MINUTES * 60000) return [];   // ждём следующего окна
if (!base.text_html && !p.image_base64 && !p.img) {
  return [{ json: { ...base, action: 'reject', reason: 'В посте нет ни текста, ни картинки' } }];
}

const plain = base.text_html.replace(/<[^>]+>/g, '')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&amp;/g, '&');

if (p.img && !p.image_base64) {
  const html = '<a href="' + String(p.img).replace(/"/g, '%22') + '">&#8203;</a>' + base.text_html;
  return [{ json: { ...base, text_html: html, preview: true, action: 'text', needText: true } }];
}
if (p.image_base64) {
  const short = plain.length <= CAPTION_LIMIT;
  return [{
    json: { ...base, action: 'photo', caption: short ? base.text_html : '', needText: !short && plain.length > 0 },
    binary: { photo: { data: p.image_base64, mimeType: p.image_mime || 'image/jpeg', fileName: base.id + '.jpg' } }
  }];
}
return [{ json: { ...base, action: 'text', needText: true } }];

// === Итог: записать результат в sent/ ===
const s = $getWorkflowStaticData('global');
s.lastSentAt = s.lastSentAt || {};
s.chatByFile = s.chatByFile || {};
const p = $('Подготовить').first().json;
function mid(node) { try { return $(node).first().json.result.message_id; } catch (e) { return null; } }
const photoId = mid('Отправить картинку');
const textId = mid('Отправить текст');
const lastId = textId || photoId;
s.lastSentAt[p.chat_id] = Date.now();
delete s.chatByFile[p.file];
const record = {
  id: p.id, channel: p.channel, chat_id: p.chat_id,
  photo_message_id: photoId, text_message_id: textId,
  link: 'https://t.me/' + String(p.chat_id).replace('@', '') + '/' + lastId,
  file: p.file, due_at: p.due || null, published_at: new Date().toISOString(),
  published_by: 'n8n-server', workflow: 'v3.2'
};
s.doneFiles = s.doneFiles || {};
s.doneFiles[p.file] = p.sha;
return [{ json: {
  path: 'sent/' + p.id + '.json',
  message: 'sent ' + p.id + ' (n8n)',
  content: Buffer.from(JSON.stringify(record, null, 2)).toString('base64'),
  file: p.file, sha: p.sha
} }];

// === Ошибка: перенести пост в failed/ и сделать паузу ===
// Пост не теряется: файл целиком копируется в failed/ с описанием ошибки.
const PAUSE_MINUTES = $('Настройки').first().json.pause_minutes;
const s = $getWorkflowStaticData('global');
const p = $('Подготовить').first().json;
const original = $('Скачать пост').first().json;
function mid(node) { try { return $(node).first().json.result.message_id; } catch (e) { return null; } }
const inErr = $input.first().json.error;
const err = inErr ? (inErr.message || JSON.stringify(inErr)) : (p.reason || 'неизвестная ошибка');
const isTelegramError = p.action !== 'reject';
if (isTelegramError) s.pauseUntil = Date.now() + PAUSE_MINUTES * 60000;
const record = { ...original, failed: {
  at: new Date().toISOString(), error: String(err).slice(0, 500), by: 'n8n-server v3.2',
  photo_already_sent_message_id: mid('Отправить картинку'),
  hint: 'Исправьте причину и верните файл в outbox/. Если фото уже ушло, уберите image_base64.'
} };
const stamp = new Date().toISOString().replace(/[-:]/g, '').slice(0, 13);
s.doneFiles = s.doneFiles || {};
s.doneFiles[p.file] = p.sha;
return [{ json: {
  path: 'failed/' + p.file.replace(/\.json$/, '') + '-' + stamp + '.json',
  message: 'failed ' + p.file + ' (n8n)',
  content: Buffer.from(JSON.stringify(record, null, 2)).toString('base64'),
  file: p.file, sha: p.sha,
  notify: 'Пост не опубликован: ' + p.file + '\nПричина: ' + String(err).slice(0, 300) + '\nФайл перенесён в failed/.'
} }];

// === НАСТРОЙКИ: единственное место, которое нужно менять ===
return [{ json: {
  repo: 'drokhman/channels-publisher',              // владелец/репозиторий в GitHub
  allowed: ['@chelovek_vs_ai', '@ryadom_repetitor'], // куда разрешено публиковать
  admin_chat_id: '1073319162',          // ваш личный ID в Telegram: сюда приходят ошибки и тестовые посты
  default_hour: 10,           // время выхода, если в имени файла только дата (по Москве)
  min_gap_minutes: 120,       // не чаще одного поста в канал за это время
  pause_minutes: 60,          // пауза после ошибки Telegram
  caption_limit: 1000,        // подпись к фото — до 1024 знаков
  max: {
    enabled: false,             // true — дублировать посты в MAX; false — работает как v3.1
    api: 'https://platform-api2.max.ru',
    channels: {                 // канал Telegram → chat_id канала в MAX (число). Пусто — в MAX не дублируется
      '@chelovek_vs_ai': '',
      '@ryadom_repetitor': ''
    },
    text_limit: 4000            // предел текста MAX
  },
  committer: { name: 'n8n-publisher (сервер)', email: 'publisher@channels-publisher.local' }  // подпись сервера в журнале GitHub
} }];

// === Проверка очереди: один раз сообщить, что outbox опустел ===
const cfg = $('Настройки').first().json;
const s = $getWorkflowStaticData('global');
const posts = $input.all().map(i => i.json).filter(f => f && f.type === 'file' && String(f.name).endsWith('.json'));
if (posts.length > 0) { s.emptyNotified = false; return []; }
if (s.emptyNotified) return [];
s.emptyNotified = true;
return [{ json: { notify: 'Публикатор: очередь outbox пуста, новых постов к выходу нет.' } }];

// === MAX: подготовить — продублировать опубликованный в Telegram пост в MAX ===
// Работает только после успешной отправки в Telegram (узел «Итог» записал sent/).
// Ошибка MAX не трогает Telegram: она пишется в failed-max/ и приходит вам в личку.
// В файле поста можно указать: "max": false — не дублировать; "max_text_html" — свой текст для MAX.
const cfg = $('Настройки').first().json;
const m = cfg.max || {};
if (!m.enabled) return [];
let done;
try { done = $('Итог').first().json; } catch (e) { return []; }      // Итог не выполнялся — это была ошибка
if (!done || !String(done.path || '').startsWith('sent/')) return [];
const post = $('Скачать пост').first().json;
const tg = $('Подготовить').first().json;
if (post.max === false) return [];
const maxChat = String((m.channels || {})[tg.chat_id] || '').trim();
if (!maxChat) return [];

// Telegram HTML → MAX HTML: оставляем только теги, которые MAX понимает, остальные снимаем (текст внутри сохраняется)
const KEEP = { b: 'b', strong: 'b', i: 'i', em: 'i', u: 'u', ins: 'u', s: 's', strike: 's', del: 's',
               code: 'code', pre: 'pre', a: 'a', blockquote: 'blockquote', mark: 'mark' };
function toMax(html) {
  return String(html || '').replace(/<\s*(\/?)\s*([a-zA-Z][\w-]*)([^>]*)>/g, (all, close, tag, attrs) => {
    const t = KEEP[tag.toLowerCase()];
    if (!t) return '';
    if (close) return '</' + t + '>';
    if (t === 'a') {
      const h = attrs.match(/href\s*=\s*("([^"]*)"|'([^']*)')/i);
      return h ? '<a href="' + (h[2] !== undefined ? h[2] : h[3]) + '">' : '';
    }
    return '<' + t + '>';
  });
}
const text = toMax(post.max_text_html || post.text_html || post.text || '');
const plain = text.replace(/<[^>]+>/g, '');
const base = { id: tg.id, file: tg.file, channel: tg.channel, tg_chat_id: tg.chat_id, max_chat_id: maxChat,
               tg_link: (() => { try { return JSON.parse(Buffer.from(done.content, 'base64').toString()).link; } catch (e) { return null; } })() };
const LIMIT = m.text_limit || 4000;
if (text.length > LIMIT) {
  return [{ json: { ...base, upload: false, skip_reason: 'Текст для MAX длиннее ' + LIMIT + ' знаков (' + text.length + ' с тегами, ' + plain.length + ' без). Сократите или задайте max_text_html.' } }];
}
const body = { text, format: 'html' };
if (post.image_base64) {
  return [{ json: { ...base, upload: true, body },
            binary: { photo: { data: post.image_base64, mimeType: post.image_mime || 'image/jpeg', fileName: (tg.id || 'post') + '.jpg' } } }];
}
if (post.img) body.attachments = [{ type: 'image', payload: { url: String(post.img) } }];
return [{ json: { ...base, upload: false, body } }];

// === MAX: файл к загрузке — соединить адрес загрузки и картинку ===
const prep = $('MAX: подготовить').first();
const r = $input.first().json;
if (!r.url) throw new Error('MAX не выдал адрес загрузки: ' + JSON.stringify(r).slice(0, 300));
return [{ json: { upload_url: r.url, upload_token: r.token || null }, binary: prep.binary }];

// === MAX: вложение — токен загруженной картинки в тело сообщения ===
const prep = $('MAX: подготовить').first().json;
const r = $input.first().json || {};
const t = $('MAX: файл к загрузке').first().json;
let payload = null;
if (r.photos && Object.keys(r.photos).length) payload = { photos: r.photos };
else if (r.token) payload = { token: r.token };
else if (t.upload_token) payload = { token: t.upload_token };
if (!payload) throw new Error('MAX не вернул токен картинки: ' + JSON.stringify(r).slice(0, 300));
return [{ json: { ...prep, body: { ...prep.body, attachments: [{ type: 'image', payload }] } } }];

// === MAX: тело — единая точка перед отправкой (с картинкой или без) ===
const j = $input.first().json;
if (j.skip_reason) return [{ json: { ...j, route: 'fail', attempts: 0, error: j.skip_reason } }];
return [{ json: j }];

// === MAX: проверить ответ (попытка 1) ===
// Повтор только при attachment.not.ready — тогда пост точно не опубликован. Любая другая ошибка — без повтора, чтобы не было дубля.
const r = $input.first().json;
const status = r.statusCode;
let b = r.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) {} }
b = b || {};
const prev = $('MAX: тело').first().json;
if (status >= 200 && status < 300 && b.message) {
  const msg = b.message;
  return [{ json: { ...prev, route: 'ok', attempts: 1, max_mid: (msg.body && msg.body.mid) || null, max_url: msg.url || null } }];
}
const code = b.code || '';
const err = 'HTTP ' + status + ': ' + (code ? code + ' — ' : '') + (b.message || JSON.stringify(b)).toString().slice(0, 300);
if (code === 'attachment.not.ready' && !false) return [{ json: { ...prev, route: 'retry', attempts: 1, error: err } }];
return [{ json: { ...prev, route: 'fail', attempts: 1, error: err } }];

// === MAX: проверить ответ (попытка 2) ===
// Повтор только при attachment.not.ready — тогда пост точно не опубликован. Любая другая ошибка — без повтора, чтобы не было дубля.
const r = $input.first().json;
const status = r.statusCode;
let b = r.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) {} }
b = b || {};
const prev = $('MAX: тело').first().json;
if (status >= 200 && status < 300 && b.message) {
  const msg = b.message;
  return [{ json: { ...prev, route: 'ok', attempts: 2, max_mid: (msg.body && msg.body.mid) || null, max_url: msg.url || null } }];
}
const code = b.code || '';
const err = 'HTTP ' + status + ': ' + (code ? code + ' — ' : '') + (b.message || JSON.stringify(b)).toString().slice(0, 300);
if (code === 'attachment.not.ready' && !true) return [{ json: { ...prev, route: 'retry', attempts: 2, error: err } }];
return [{ json: { ...prev, route: 'fail', attempts: 2, error: err } }];

// === MAX: итог — запись в sent-max/ ===
const j = $input.first().json;
const record = { id: j.id, channel: j.channel, tg_chat_id: j.tg_chat_id, tg_link: j.tg_link,
  max_chat_id: j.max_chat_id, max_mid: j.max_mid, max_url: j.max_url, attempts: j.attempts,
  file: j.file, published_at: new Date().toISOString(), published_by: 'n8n-server', workflow: 'v3.2' };
return [{ json: { path: 'sent-max/' + j.id + '.json', message: 'sent-max ' + j.id + ' (n8n)',
  content: Buffer.from(JSON.stringify(record, null, 2)).toString('base64') } }];

// === MAX: ошибка — пост целиком в failed-max/, сообщение вам. Telegram уже опубликован и не повторяется ===
const j = $input.first().json;
const original = $('Скачать пост').first().json;
const record = { ...original, failed_max: { at: new Date().toISOString(), error: String(j.error || 'неизвестная ошибка').slice(0, 500),
  attempts: j.attempts || 0, max_chat_id: j.max_chat_id, tg_link: j.tg_link, by: 'n8n-server v3.2',
  hint: 'В Telegram пост уже вышел. В MAX его нет: опубликуйте вручную или после исправления причины.' } };
const stamp = new Date().toISOString().replace(/[-:]/g, '').slice(0, 13);
return [{ json: { path: 'failed-max/' + j.id + '-' + stamp + '.json', message: 'failed-max ' + j.id + ' (n8n)',
  content: Buffer.from(JSON.stringify(record, null, 2)).toString('base64'),
  notify: 'MAX: пост не опубликован — ' + j.id + '\nПричина: ' + String(j.error || '').slice(0, 300) + '\nTelegram: ' + (j.tg_link || 'опубликован') + '\nФайл в failed-max/.' } }];

// === MAX: ошибка загрузки картинки ===
const prep = $('MAX: подготовить').first().json;
const e = $input.first().json.error;
return [{ json: { ...prep, route: 'fail', attempts: 0, error: 'Загрузка картинки: ' + (e ? (e.message || JSON.stringify(e)) : 'неизвестно') } }];
